"""Freeze compact local evidence; omit large binaries and inert bytecode explicitly."""
import hashlib,json,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
HERE=Path(__file__).resolve().parent
OUT=ROOT/'evidence/fringe-shading-color-v1'
SOURCES=['outputs/fringe-shading-review-v1', 'outputs/fringe-culling-native-control-v1', 'outputs/export-preview-engine-tests-v1', 'outputs/fringe-color-atlas-analytic-v1', 'outputs/fringe-shading-candidate-preparation-v1', 'outputs/panda-fringe-source-normal-v1', 'outputs/fringe-source-normal-audit-v1', 'outputs/fringe-baseline-eevee-preview-preparation-v1', 'outputs/panda-fringe-area-eevee-preview-v1', 'outputs/fringe-source-normal-eevee-preview-preparation-v1', 'outputs/panda-fringe-normal-eevee-preview-v1', 'outputs/fringe-preview-integration-tests-v1', 'outputs/fringe-normal-comparison-review-v1', 'outputs/fringe-color-candidate-preparation-v1', 'outputs/panda-fringe-color-atlas-v1', 'outputs/fringe-combined-candidate-preparation-v1', 'outputs/panda-fringe-color-source-normal-v1', 'outputs/fringe-color-eevee-preview-preparation-v1', 'outputs/panda-fringe-color-eevee-preview-v1', 'outputs/fringe-combined-eevee-preview-preparation-v1', 'outputs/panda-fringe-combined-eevee-preview-v1', 'outputs/fringe-four-way-review-v1', 'outputs/fringe-part-ownership-review-v1', 'outputs/fringe-shading-color-save-v1']
def sha(path):
 h=hashlib.sha256()
 with path.open('rb') as stream:
  for chunk in iter(lambda:stream.read(1024*1024),b''):h.update(chunk)
 return h.hexdigest()
files=[]
for folder in SOURCES:
 for path in sorted((ROOT/folder).rglob('*')):
  assert not path.is_symlink(),path
  if path.is_file():files.append(path)
assert len(files)<=512
rows=[];omitted=[];objects={};total=0
for path in files:
 size=path.stat().st_size
 assert size<=128*1024*1024,path
 row={'origin':str(path.relative_to(ROOT)),'bytes':size,'sha256':sha(path)}
 if size>2*1024*1024 or path.suffix in ('.glb','.blend','.pyc'):
  row['reason']='Large model/native file remains local; compact evidence is not a remote binary backup.' if path.suffix!='.pyc' else 'Generated bytecode omitted; exact Python source retained.'
  omitted.append(row);continue
 key=row['sha256']
 if key not in objects:
  objects[key]='payload/'+key+'/'+path.name
  total+=size
 row['saved_path']=objects[key];rows.append(row)
assert total<=16*1024*1024,(total,'bundle exceeds bound')
OUT.mkdir()
for row in rows:
 src=ROOT/row['origin'];dest=OUT/row['saved_path']
 assert sha(src)==row['sha256']
 if not dest.exists():
  dest.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(src,dest)
 assert sha(dest)==row['sha256']
readme="# Exported renderer and fur color/shading evidence\n\n**A corrected preview renderer and partial fur improvement, not an accepted\nhands-off avatar or dense/Muse-equivalent coat.**\n\n`manifest.json` maps exact local origins to deduplicated immutable payloads.\nIt retains the actual glTF culling control, production renderer source/tests,\nanalytic color-atlas helper, three new actual model builds, independent normal\nand part-ownership audits, all32 matched EEVEE previews, and parent reviews.\nLarge GLB/Blend files remain local with hashes; this is not their remote backup.\n\nKey origins:\n\n- `outputs/fringe-culling-native-control-v1/findings.json`\n- `outputs/export-preview-engine-tests-v1/test-receipt.json`\n- `outputs/fringe-color-atlas-analytic-v1/RESULTS.md`\n- `outputs/panda-fringe-color-atlas-v1/color-error-audit.json`\n- `outputs/fringe-source-normal-audit-v1/audit.json`\n- `outputs/fringe-four-way-review-v1/review.json`\n- `outputs/fringe-part-ownership-review-v1/review.md`\n\nSix new renderer tests and49 focused integration checks passed. A real fixture\nshows the pinned Cycles path ignores tested single-sided glTF culling; bounded\nEEVEE passes that control. Native hair/portrait rendering stays unchanged.\n\nMatched actual previews show source-surface normals remove most white-body\nspeckling. The new atlas reduces nominal-tip errors above0.1 from194 to0 atLOD0,\nbut the combined coat still shows dark-region light flecks. Minification remains\nunder separate investigation and is not included in this completed bundle.\nThere is no fur assignment leak to the dragon. Contact/source defects persist;\nno default, gallery or automatic fur-profile promotion is made.\n\nNo Meshy, Meta, image-generation or pipeline-role AI calls ran. Existing approved\nassets, Weft's consumer/physics, original reference and spending limits remain\nunchanged. Rights/provenance are inherited from pinned source manifests, not\nindependently verified. Exact commands/settings and bounds remain in preparations.\nCompleted append-only execution scripts must not be rerun in their old folders.\n"
(OUT/'README.md').write_text(readme)
manifest={'schema_version':1,'project_relative_root':'tools/avatar-assets','status':'renderer_corrected_fur_partial_not_quality_accepted','quality_approved':False,'muse_parity':False,'hands_off_acceptance':False,'origin_mappings':rows,'omitted_origin_files':omitted,'source_directories':SOURCES,'payload_object_count':len(objects),'payload_object_bytes':total,'retained_origin_count':len(rows),'bundle_limits':{'max_bytes':16*1024*1024,'max_source_files':512},'new_provider_or_pipeline_role_calls':0,'artifacts':[{'path':'README.md','bytes':(OUT/'README.md').stat().st_size,'sha256':sha(OUT/'README.md')}],'limitations':['Not a remote backup or complete recreation of omitted binaries.','Renderer/LOD0/root integrity does not establish full appearance, GPU texture filtering or fresh Studio acceptance.']}
(OUT/'manifest.json').write_text(json.dumps(manifest,indent=2,sort_keys=True)+'\n')
for row in rows:assert sha(ROOT/row['origin'])==row['sha256'] and sha(OUT/row['saved_path'])==row['sha256']
receipt={'manifest_sha256':sha(OUT/'manifest.json'),'bundle_files':len(list(OUT.rglob('*')))-len([p for p in OUT.rglob('*') if p.is_dir()]),'bundle_bytes':sum(p.stat().st_size for p in OUT.rglob('*') if p.is_file()),'origins':len(rows),'omitted_files':len(omitted),'all_retained_copies_verified':True}
(HERE/'receipt.json').write_text(json.dumps(receipt,indent=2)+'\n')
print(json.dumps(receipt,indent=2))
